/*
 * Accepts inputs from stdin and pass them to the library, and pass library's output to stdout.
 */
#include <iostream>
#include "cfg_mgr.h" // library
#include "cfg.h" // generated by script
#include "cfg_mgr_strtok.h" // library class strtok

using namespace std;

cfg_mgr::Descriptor * get_base_descriptor();

#define WORD_DELIMITERS " \n"
#define BLOCK_DELIMITER "\""

static void handle_command(cfg_mgr::Config_manager & cm);

// Pointer to RAM memory holding configuration managed by the library.
t_device * pCfg = nullptr;

int main(int argc, char **argv)
{
    if (argc < 2)
    {
        // Must provide 1 parameter, NVRAM file name.
        printf("This app takes 1 parameter: the name of the NVRAM file.\n");
        return 1;
    }

    // Initialize the config manager with the base descriptor it is to manage.
    // Pass function printf to library, so it can send its output to stdout.
    cfg_mgr::Config_manager cm(get_base_descriptor(), argv[1], printf, (uint8_t **)&pCfg);

    while (true)
    {
        handle_command(cm);
    }
    return 0;
}

// Get command from stdin and pass it to Config_manager.
// Pass output from Config_manager to stdout.
void handle_command(cfg_mgr::Config_manager & cm)
{
    printf("%s>\n", cm.getPromptString());
    fflush(stdout);

    char cmd[120];
    if (fgets(cmd, sizeof(cmd), stdin) == nullptr)
    {
        return;
    }

    // Break commands into a list of tokens, as expected by config manager
    char *param[20];
    cfg_mgr::Strtok strtok(cmd);
    unsigned int wordCnt = 0;
    while ((param[wordCnt] = strtok(WORD_DELIMITERS, BLOCK_DELIMITER)))
    {
        wordCnt++;
    }
    cm.handleCmd(wordCnt, param);
    fflush(stdout);
}
